        if (!cached) {
            constexpr std::array<std::u16string_view, 3> names{u"NORMAL", u"SPANNABLE", u"EDITABLE"};
            cached = own(runtime.new_host_enum(buffer_mode_type, names[static_cast<std::size_t>(mode)], mode));
        }
