        if (cell.presence != StyledAttributePresence::present || cell.scalar != StyledScalarStatus::ready || cell.value.type != 5)
            bad("WIDGET_STYLEABLE_UNSUPPORTED", "Widget requires an actual dimension: " + std::string(name));
